"""Canonical Flow contracts for the Shaper-to-Delivery boundary.

These records are runtime-neutral authority. Providers and MAF receive a later
projection and cannot add fields to these sealed artifacts.
"""

from __future__ import annotations

import hashlib
import json
from typing import Any

from runner_limits import MAX_ACTIONS, MAX_MANAGER_CALLS, MAX_MANAGER_ROUNDS, MAX_VERIFIER_CALLS


SCHEMA_VERSION = 1
SHAPER_CONTRACT_VERSION = 3
DELIVERY_CHARTER_VERSION = 3
# v2 records predate sealed expansion headroom; v1 records predate the
# verifier allowance. Both stay readable for already-sealed runs.
VERIFIER_SHAPER_CONTRACT_VERSION = 2
VERIFIER_DELIVERY_CHARTER_VERSION = 2
LEGACY_SHAPER_CONTRACT_VERSION = 1
LEGACY_DELIVERY_CHARTER_VERSION = 1
SHAPER_CONTRACT_VERSIONS = {LEGACY_SHAPER_CONTRACT_VERSION, VERIFIER_SHAPER_CONTRACT_VERSION, SHAPER_CONTRACT_VERSION}
DELIVERY_CHARTER_VERSIONS = {LEGACY_DELIVERY_CHARTER_VERSION, VERIFIER_DELIVERY_CHARTER_VERSION, DELIVERY_CHARTER_VERSION}

CAPABILITY_TO_RUNTIME = {
    "scoped-edit": ["read", "edit"],
    "read-only-review": ["read"],
    "bounded-verification": ["read"],
}
ENFORCEABLE_LIMIT_FIELDS = {
    "max_concurrent", "max_replans", "runtime_seconds", "tools", "paths",
    "outputs", "retries", "max_manager_calls", "max_manager_rounds",
    "max_paid_worker_calls",
}
# Limits a Shaper may pre-approve growth for, mapped to their runner ceiling.
# Replans and concurrency are deliberately absent: they are never expandable.
EXPANSION_CEILINGS = {
    "delegations": MAX_ACTIONS,
    "paid_worker_calls": MAX_ACTIONS,
    "verifier_calls": MAX_VERIFIER_CALLS,
    "manager_calls": MAX_MANAGER_CALLS,
    "manager_rounds": MAX_MANAGER_ROUNDS,
}


class DeliveryContractError(ValueError):
    pass


def canonical(value: Any) -> str:
    try:
        return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
    except (TypeError, ValueError) as exc:
        raise DeliveryContractError(f"record is not canonical JSON: {exc}") from exc


def digest(value: Any) -> str:
    return hashlib.sha256(canonical(value).encode("utf-8")).hexdigest()


def _text(value: object, field: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise DeliveryContractError(f"{field} must be a non-empty string")
    return value


def _sha(value: object, field: str) -> str:
    if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
        raise DeliveryContractError(f"{field} must be a lowercase SHA-256 digest")
    return value


def _list(value: object, field: str, *, nonempty: bool = False) -> list[Any]:
    if not isinstance(value, list) or (nonempty and not value):
        raise DeliveryContractError(f"{field} must be {'a non-empty ' if nonempty else 'a '}list")
    return value


def _mapping(value: object, field: str, *, keys: set[str] | None = None) -> dict[str, Any]:
    if not isinstance(value, dict) or (keys is not None and set(value) != keys):
        raise DeliveryContractError(f"{field} is invalid")
    return value


def _sources(sources: object, work_id: str) -> dict[str, dict[str, str]]:
    sources = _mapping(sources, "approved_sources")
    required = {"requirements", "acceptance_criteria"}
    if not required.issubset(sources):
        raise DeliveryContractError("approved_sources must include requirements and acceptance_criteria")
    prefix = f".flow/runs/{work_id}/"
    normalized: dict[str, dict[str, str]] = {}
    for name, source in sorted(sources.items()):
        source = _mapping(source, f"source {name}", keys={"path", "sha256"})
        path = _text(source["path"], f"source {name} path")
        if not path.startswith(prefix) or any(part in {"", ".", ".."} for part in path.split("/")):
            raise DeliveryContractError(f"source {name} path is outside the current run")
        normalized[name] = {"path": path, "sha256": _sha(source["sha256"], f"source {name} sha256")}
    return normalized


def validate_expansion_headroom(headroom: object, base: dict[str, int]) -> dict[str, int]:
    """Return the full headroom map, refusing anything the runner cannot run.

    ``base`` holds the sealed limit for every expandable name. Base plus
    headroom must stay within the runner ceiling, and paid calls can never
    outgrow delegations, because every paid call is a delegation.
    """
    if not isinstance(headroom, dict) or not set(headroom) <= set(EXPANSION_CEILINGS):
        raise DeliveryContractError("expansion_headroom has an unknown or non-expandable limit")
    full = {name: headroom.get(name, 0) for name in EXPANSION_CEILINGS}
    for name, value in full.items():
        if type(value) is not int or value < 0:
            raise DeliveryContractError(f"expansion_headroom {name} must be a non-negative integer")
        if type(base.get(name)) is not int or base[name] + value > EXPANSION_CEILINGS[name]:
            raise DeliveryContractError(f"{name} limit plus headroom exceeds the runner ceiling")
    if base["paid_worker_calls"] + full["paid_worker_calls"] > base["delegations"] + full["delegations"]:
        raise DeliveryContractError("paid-worker headroom exceeds delegation headroom")
    return full


def _expansion_base(delegations: int, paid: int, verifier: int, manager_calls: int, manager_rounds: int) -> dict[str, int]:
    return {"delegations": delegations, "paid_worker_calls": paid, "verifier_calls": verifier,
            "manager_calls": manager_calls, "manager_rounds": manager_rounds}


def _claim(value: str, sources: dict[str, dict[str, str]]) -> dict[str, Any]:
    return {"value": value, "provenance": [{"source": name, "sha256": source["sha256"], "claim_status": "approved"} for name, source in sorted(sources.items())]}


INTENT_FIELDS = {
    "problem", "intended_users", "outcomes", "scope", "exclusions", "constraints",
    "assumptions", "acceptance_criteria", "risks", "open_decisions", "decision_owners",
    "allowed_specialists", "prohibited_capabilities", "delegation_matrix", "approval_matrix",
    "budget_safety_envelope", "boundaries", "amendment_lineage", "approval_history",
    "next_lane_eligibility",
}


def validate_shaper_intent(intent: object) -> dict[str, Any]:
    """Normalize approved intent for the v2 contract without mutating callers.

    V1 intent did not carry a verifier allowance.  New contracts preserve that
    input as an explicit default of two total verifier calls.
    """
    if not isinstance(intent, dict) or not INTENT_FIELDS <= set(intent) <= INTENT_FIELDS | {"max_verifier_calls", "expansion_headroom"}:
        raise DeliveryContractError("shaper_intent is invalid")
    intent = dict(intent)
    intent.setdefault("max_verifier_calls", 2)
    intent.setdefault("expansion_headroom", {})
    _text(intent["problem"], "problem")
    for name in ("intended_users", "outcomes", "scope", "exclusions", "constraints", "assumptions", "acceptance_criteria"):
        values = _list(intent[name], name, nonempty=True)
        for value in values:
            _text(value, name)
    for name in ("risks", "open_decisions", "decision_owners", "allowed_specialists", "prohibited_capabilities", "amendment_lineage", "approval_history", "next_lane_eligibility"):
        _list(intent[name], name, nonempty=name in {"risks", "allowed_specialists", "prohibited_capabilities", "approval_history", "next_lane_eligibility"})
    for name in ("delegation_matrix", "approval_matrix", "budget_safety_envelope", "boundaries"):
        _mapping(intent[name], name)
    for specialist in intent["allowed_specialists"]:
        specialist = _mapping(specialist, "allowed specialist", keys={"role", "capabilities", "definition_digest", "maximum_instances"})
        _text(specialist["role"], "allowed specialist role")
        capabilities = _list(specialist["capabilities"], "allowed specialist capabilities", nonempty=True)
        if len(capabilities) != len(set(capabilities)) or any(capability not in CAPABILITY_TO_RUNTIME for capability in capabilities):
            raise DeliveryContractError("allowed specialist capabilities contain an unsupported or duplicate value")
        _sha(specialist["definition_digest"], "allowed specialist definition_digest")
        if type(specialist["maximum_instances"]) is not int or specialist["maximum_instances"] < 1:
            raise DeliveryContractError("allowed specialist maximum_instances is invalid")
    if intent["approval_matrix"].get("provider_dispatch") != "Flow_grant":
        raise DeliveryContractError("provider dispatch must require a Flow grant")
    delegation = intent["delegation_matrix"]
    if set(delegation) != {"max_delegations", "delegated_expansion"} or type(delegation["max_delegations"]) is not int or delegation["max_delegations"] < 1:
        raise DeliveryContractError("delegation_matrix is invalid")
    envelope = intent["budget_safety_envelope"]
    if set(envelope) != {"enforceable", "observations"}:
        raise DeliveryContractError("budget_safety_envelope is invalid")
    enforceable = _mapping(envelope["enforceable"], "budget_safety_envelope enforceable", keys=ENFORCEABLE_LIMIT_FIELDS)
    for name in ("max_concurrent", "max_replans", "runtime_seconds", "retries", "max_manager_calls", "max_manager_rounds", "max_paid_worker_calls"):
        minimum = 1 if name in {"max_concurrent", "runtime_seconds", "max_manager_calls", "max_manager_rounds"} else 0
        if type(enforceable[name]) is not int or enforceable[name] < minimum:
            raise DeliveryContractError(f"{name} is invalid")
    for name in ("tools", "paths", "outputs"):
        values = _list(enforceable[name], name, nonempty=True)
        if len(values) != len(set(values)) or any(not isinstance(value, str) or not value for value in values):
            raise DeliveryContractError(f"{name} is invalid")
    if not set(enforceable["tools"]).issubset({"read", "edit", "test"}) or enforceable["paths"] != ["charter-scoped"] or not set(enforceable["outputs"]).issubset({"diff", "test", "receipt"}):
        raise DeliveryContractError("enforceable tools, paths, or outputs are unsupported")
    if enforceable["max_concurrent"] > delegation["max_delegations"] or enforceable["max_paid_worker_calls"] > delegation["max_delegations"]:
        raise DeliveryContractError("concurrency or paid-worker limit exceeds max_delegations")
    if type(intent["max_verifier_calls"]) is not int or intent["max_verifier_calls"] not in {1, 2}:
        raise DeliveryContractError("max_verifier_calls must be one or two")
    intent["expansion_headroom"] = validate_expansion_headroom(intent["expansion_headroom"], _expansion_base(
        delegation["max_delegations"], enforceable["max_paid_worker_calls"], intent["max_verifier_calls"],
        enforceable["max_manager_calls"], enforceable["max_manager_rounds"]))
    # The flag is derived, never independent: it states whether any headroom exists.
    if type(delegation["delegated_expansion"]) is not bool or delegation["delegated_expansion"] != any(intent["expansion_headroom"].values()):
        raise DeliveryContractError("delegated_expansion must state whether any expansion headroom is sealed")
    _list(envelope["observations"], "budget_safety_envelope observations")
    return intent


def _intent(work_id: str, sources: dict[str, dict[str, str]], approved: dict[str, Any]) -> dict[str, Any]:
    """Project a reviewed per-run intent artifact without guessing Markdown semantics."""
    approved = validate_shaper_intent(approved)
    claimed = lambda value: _claim(value, sources)
    return {
        "problem": claimed(approved["problem"]),
        **{name: [claimed(value) for value in approved[name]] for name in
           ("intended_users", "outcomes", "scope", "exclusions", "constraints", "assumptions", "acceptance_criteria")},
        "source_evidence": [{"source": name, "sha256": source["sha256"], "claim_status": "approved", "provenance": source["path"]} for name, source in sorted(sources.items())],
        **{name: approved[name] for name in ("risks", "open_decisions", "decision_owners", "allowed_specialists",
           "prohibited_capabilities", "delegation_matrix", "approval_matrix", "budget_safety_envelope", "max_verifier_calls",
           "expansion_headroom", "boundaries", "amendment_lineage", "approval_history", "next_lane_eligibility")},
    }


def _seal(record: dict[str, Any], validator) -> dict[str, Any]:
    result = dict(record)
    result["digest"] = digest(result)
    validator(result)
    return result


def build_shaper_contract(work_id: str, sources: dict[str, dict[str, str]], intent: dict[str, Any], *, approval_event: str = "approve-definition") -> dict[str, Any]:
    work_id = _text(work_id, "run_id")
    sources = _sources(sources, work_id)
    intent = _intent(work_id, sources, intent)
    record = {
        "schema_version": SCHEMA_VERSION, "version": SHAPER_CONTRACT_VERSION, "kind": "shaper_contract",
        "shaper_contract_id": f"shaper-{digest({'run_id': work_id, 'sources': sources})[:20]}",
        "run_id": work_id, "status": "approved", "approved_sources": sources,
        "approval_event": _text(approval_event, "approval_event"), **intent,
    }
    return _seal(record, validate_shaper_contract)


def build_delivery_charter(shaper: dict[str, Any]) -> dict[str, Any]:
    validate_shaper_contract(shaper)
    charter_id = f"delivery-{digest({'shaper': shaper['digest']})[:20]}"
    definitions = {}
    for item in shaper["allowed_specialists"]:
        runtime_capabilities = sorted({runtime for capability in item["capabilities"] for runtime in CAPABILITY_TO_RUNTIME[capability]})
        if item["role"] in definitions:
            raise DeliveryContractError("allowed specialist role is duplicated")
        definitions[item["role"]] = {"definition_digest": item["definition_digest"], "maximum_instances": item["maximum_instances"],
                                     "approved_capabilities": item["capabilities"], "runtime_capabilities": runtime_capabilities}
    enforceable = shaper["budget_safety_envelope"]["enforceable"]
    record = {
        "schema_version": SCHEMA_VERSION, "charter_version": DELIVERY_CHARTER_VERSION, "kind": "delivery_charter",
        "charter_id": charter_id, "run_id": shaper["run_id"], "delivery_attempt_policy": {"one_active_lead": True, "resume_or_supersede": "explicit"},
        "shaper_contract": {"id": shaper["shaper_contract_id"], "version": shaper["version"], "digest": shaper["digest"]},
        "approved_sources": shaper["approved_sources"], "outcomes": shaper["outcomes"], "scope": shaper["scope"],
        "exclusions": shaper["exclusions"], "constraints": shaper["constraints"], "acceptance_criteria": shaper["acceptance_criteria"],
        "accepted_risks": shaper["risks"], "eligible_specialists": definitions,
        "prohibited_capabilities": shaper["prohibited_capabilities"],
        "provider_capabilities": {"claude": {"binding": "capability"}, "codex": {"binding": "capability"}, "ollama": {"binding": "verifier"}},
        "limits": {"delegations": shaper["delegation_matrix"]["max_delegations"],
                   "concurrency": enforceable["max_concurrent"], "replans": enforceable["max_replans"],
                   **{name: enforceable[name] for name in ("runtime_seconds", "tools", "paths", "outputs", "retries", "max_manager_calls", "max_manager_rounds", "max_paid_worker_calls")},
                   "max_verifier_calls": shaper["max_verifier_calls"],
                   "expansion_headroom": shaper["expansion_headroom"]},
        "approval_matrix": shaper["approval_matrix"], "producer_verifier_rules": {"distinct_identities": True, "verifier_read_only": True},
        "validation": {"flow_observed_diff_and_test_before_verifier": True}, "recovery": {"unknown_action_blocks_successor": True, "takeover": "explicit_resume_or_supersede"},
        "escalation_stop_cancellation": {"scope_expansion": "halt_for_shaper", "cancellation": "Flow_only"},
        "boundaries": shaper["boundaries"], "handback": ["receipt", "diff", "test", "verifier_evidence"],
        "approver": {"identity": "engineer", "event": shaper["approval_event"]}, "amendment_lineage": shaper["amendment_lineage"], "compatibility_version": 7,
    }
    return _seal(record, validate_delivery_charter)


def _validate_digest(record: dict[str, Any], label: str) -> None:
    expected = dict(record)
    actual = expected.pop("digest", None)
    if _sha(actual, f"{label} digest") != digest(expected):
        raise DeliveryContractError(f"{label} digest mismatch")


def validate_shaper_contract(record: dict[str, Any]) -> None:
    if not isinstance(record, dict) or record.get("schema_version") != SCHEMA_VERSION or record.get("version") not in SHAPER_CONTRACT_VERSIONS or record.get("kind") != "shaper_contract":
        raise DeliveryContractError("unsupported Shaper Contract version")
    work_id = _text(record.get("run_id"), "run_id")
    _text(record.get("shaper_contract_id"), "shaper_contract_id")
    if record.get("status") != "approved":
        raise DeliveryContractError("Shaper Contract must be approved")
    _sources(record.get("approved_sources"), work_id)
    _text(record.get("approval_event"), "approval_event")
    required_lists = ("intended_users", "outcomes", "scope", "exclusions", "constraints", "assumptions", "acceptance_criteria", "source_evidence", "risks", "open_decisions", "decision_owners", "allowed_specialists", "prohibited_capabilities", "amendment_lineage", "approval_history", "next_lane_eligibility")
    _mapping(record.get("problem"), "problem", keys={"value", "provenance"})
    for name in required_lists:
        _list(record.get(name), name, nonempty=name not in {"open_decisions", "decision_owners", "amendment_lineage"})
    roles: set[str] = set()
    for specialist in record["allowed_specialists"]:
        specialist = _mapping(specialist, "allowed specialist", keys={"role", "capabilities", "definition_digest", "maximum_instances"})
        role = _text(specialist["role"], "allowed specialist role")
        if role in roles:
            raise DeliveryContractError("allowed specialist role is duplicated")
        roles.add(role)
        capabilities = _list(specialist["capabilities"], "allowed specialist capabilities", nonempty=True)
        if len(capabilities) != len(set(capabilities)) or any(capability not in CAPABILITY_TO_RUNTIME for capability in capabilities):
            raise DeliveryContractError("allowed specialist capabilities contain an unsupported or duplicate value")
        _sha(specialist["definition_digest"], "allowed specialist definition_digest")
        if type(specialist["maximum_instances"]) is not int or specialist["maximum_instances"] < 1:
            raise DeliveryContractError("allowed specialist maximum_instances is invalid")
    for name in ("delegation_matrix", "approval_matrix", "budget_safety_envelope", "boundaries"):
        _mapping(record.get(name), name)
    if record["approval_matrix"].get("provider_dispatch") != "Flow_grant":
        raise DeliveryContractError("provider dispatch must require a Flow grant")
    if record["version"] != LEGACY_SHAPER_CONTRACT_VERSION:
        if type(record.get("max_verifier_calls")) is not int or record["max_verifier_calls"] not in {1, 2}:
            raise DeliveryContractError("Shaper Contract max_verifier_calls is invalid")
    elif "max_verifier_calls" in record:
        raise DeliveryContractError("legacy Shaper Contract cannot carry max_verifier_calls")
    if record["version"] == SHAPER_CONTRACT_VERSION:
        delegation = record["delegation_matrix"]
        enforceable = _mapping(record["budget_safety_envelope"].get("enforceable"), "budget_safety_envelope enforceable")
        headroom = validate_expansion_headroom(record.get("expansion_headroom"), _expansion_base(
            delegation.get("max_delegations"), enforceable.get("max_paid_worker_calls"), record["max_verifier_calls"],
            enforceable.get("max_manager_calls"), enforceable.get("max_manager_rounds")))
        if headroom != record["expansion_headroom"] or delegation.get("delegated_expansion") is not any(headroom.values()):
            raise DeliveryContractError("Shaper Contract expansion headroom is invalid")
    elif "expansion_headroom" in record or record["delegation_matrix"].get("delegated_expansion") is not False:
        raise DeliveryContractError("pre-expansion Shaper Contract cannot carry expansion headroom")
    _validate_digest(record, "Shaper Contract")


def validate_delivery_charter(record: dict[str, Any]) -> None:
    if not isinstance(record, dict) or record.get("schema_version") != SCHEMA_VERSION or record.get("charter_version") not in DELIVERY_CHARTER_VERSIONS or record.get("kind") != "delivery_charter":
        raise DeliveryContractError("unsupported Delivery Charter version")
    work_id = _text(record.get("run_id"), "run_id")
    _text(record.get("charter_id"), "charter_id")
    _sources(record.get("approved_sources"), work_id)
    _mapping(record.get("delivery_attempt_policy"), "delivery_attempt_policy", keys={"one_active_lead", "resume_or_supersede"})
    if record["delivery_attempt_policy"] != {"one_active_lead": True, "resume_or_supersede": "explicit"}:
        raise DeliveryContractError("Delivery Charter attempt policy is invalid")
    source = _mapping(record.get("shaper_contract"), "shaper_contract", keys={"id", "version", "digest"})
    _text(source["id"], "shaper_contract id")
    if source["version"] not in SHAPER_CONTRACT_VERSIONS:
        raise DeliveryContractError("shaper_contract version is invalid")
    _sha(source["digest"], "shaper_contract digest")
    for name in ("outcomes", "scope", "exclusions", "constraints", "acceptance_criteria", "accepted_risks", "handback", "amendment_lineage"):
        _list(record.get(name), name, nonempty=name != "amendment_lineage")
    _mapping(record.get("eligible_specialists"), "eligible_specialists")
    for role, definition in record["eligible_specialists"].items():
        _text(role, "eligible specialist role")
        definition = _mapping(definition, "eligible specialist", keys={"definition_digest", "maximum_instances", "approved_capabilities", "runtime_capabilities"})
        _sha(definition["definition_digest"], "specialist definition digest")
        if not isinstance(definition["maximum_instances"], int) or definition["maximum_instances"] < 1:
            raise DeliveryContractError("maximum_instances is invalid")
        approved = _list(definition["approved_capabilities"], "approved specialist capabilities", nonempty=True)
        runtime = _list(definition["runtime_capabilities"], "runtime specialist capabilities", nonempty=True)
        if any(value not in CAPABILITY_TO_RUNTIME for value in approved) or runtime != sorted({item for value in approved for item in CAPABILITY_TO_RUNTIME[value]}):
            raise DeliveryContractError("specialist capability projection is invalid")
    _list(record.get("prohibited_capabilities"), "prohibited_capabilities", nonempty=True)
    _mapping(record.get("provider_capabilities"), "provider_capabilities")
    limit_keys = {"delegations", "concurrency", "replans", "runtime_seconds", "tools", "paths", "outputs", "retries", "max_manager_calls", "max_manager_rounds", "max_paid_worker_calls"}
    if record["charter_version"] != LEGACY_DELIVERY_CHARTER_VERSION:
        limit_keys.add("max_verifier_calls")
    if record["charter_version"] == DELIVERY_CHARTER_VERSION:
        limit_keys.add("expansion_headroom")
    limits = _mapping(record.get("limits"), "limits", keys=limit_keys)
    if not all(type(limits[key]) is int and limits[key] >= 0 for key in ("delegations", "concurrency", "replans", "runtime_seconds", "retries", "max_manager_calls", "max_manager_rounds", "max_paid_worker_calls")):
        raise DeliveryContractError("Delivery Charter numeric limits are invalid")
    if record["charter_version"] != LEGACY_DELIVERY_CHARTER_VERSION:
        # A charter and its Shaper Contract share one version line after v1.
        if source["version"] != record["charter_version"] or limits["max_verifier_calls"] not in {1, 2}:
            raise DeliveryContractError("Delivery Charter max_verifier_calls is invalid")
        if record["charter_version"] == DELIVERY_CHARTER_VERSION and validate_expansion_headroom(limits["expansion_headroom"], _expansion_base(
                limits["delegations"], limits["max_paid_worker_calls"], limits["max_verifier_calls"],
                limits["max_manager_calls"], limits["max_manager_rounds"])) != limits["expansion_headroom"]:
            raise DeliveryContractError("Delivery Charter expansion headroom is invalid")
    elif "max_verifier_calls" in limits:
        raise DeliveryContractError("legacy Delivery Charter cannot carry max_verifier_calls")
    for name in ("approval_matrix", "producer_verifier_rules", "validation", "recovery", "escalation_stop_cancellation", "boundaries", "approver"):
        _mapping(record.get(name), name)
    if record["approval_matrix"].get("provider_dispatch") != "Flow_grant":
        raise DeliveryContractError("provider dispatch must require a Flow grant")
    if record["compatibility_version"] != 7:
        raise DeliveryContractError("Delivery Charter compatibility version is invalid")
    _validate_digest(record, "Delivery Charter")

"""Atomic Flow-owned transition from approved intent to delivery authority."""

from __future__ import annotations

from contextlib import ExitStack, contextmanager
from datetime import datetime, timezone
import fcntl
import hashlib
import json
import os
from pathlib import Path
from typing import Any, Iterator

from delivery_contracts import build_delivery_charter, build_shaper_contract, canonical, digest
from fsutil import ensure_dir, write_atomic


class DeliveryControlError(ValueError):
    pass


def _now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


@contextmanager
def run_lock(run_dir: Path) -> Iterator[None]:
    ensure_dir(run_dir)
    path = run_dir / ".delivery.lock"
    fd = os.open(path, os.O_CREAT | os.O_RDWR | getattr(os, "O_NOFOLLOW", 0), 0o600)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
        yield
    finally:
        fcntl.flock(fd, fcntl.LOCK_UN)
        os.close(fd)


@contextmanager
def delivery_authority_guard(run_dir: Path, envelope: dict[str, Any]) -> Iterator[None]:
    """Hold the run claim stable while a v7 caller mutates or dispatches."""
    with run_lock(run_dir):
        run_path = run_dir / "run.json"
        if not run_path.is_file() or run_path.is_symlink():
            raise DeliveryControlError("delivery run authority is unavailable")
        current = json.loads(run_path.read_text())
        delivery = current.get("delivery")
        claim = envelope.get("delivery_lead_claim")
        if (not isinstance(delivery, dict) or not isinstance(claim, dict)
                or delivery.get("owner_status") != "active"
                or delivery.get("owner_generation") != claim.get("generation")
                or delivery.get("lead_claim_digest") != envelope.get("delivery_lead_claim_digest")
                or delivery.get("charter_digest") != envelope.get("delivery_charter_digest")):
            raise DeliveryControlError("delivery owner generation is stale")
        yield


def _safe_source(root: Path, work_id: str, relative: str) -> Path:
    path = root / relative
    if not relative.startswith(f".flow/runs/{work_id}/") or not path.resolve().is_relative_to(root.resolve()):
        raise DeliveryControlError(f"source path is outside the current run: {relative}")
    if not path.is_file() or path.is_symlink():
        raise DeliveryControlError(f"approved source is unavailable: {relative}")
    return path


def _source_snapshot(root: Path, work_id: str, artifacts: dict[str, str]) -> dict[str, dict[str, str]]:
    required = {"requirements", "acceptance_criteria", "shaper_intent"}
    missing = sorted(required - set(artifacts))
    if missing:
        raise DeliveryControlError("approved run is missing artifacts: " + ", ".join(missing))
    selected = {key: artifacts[key] for key in ("requirements", "acceptance_criteria", "shaper_intent", "solution", "orchestration_manifest") if artifacts.get(key)}
    snapshots: dict[str, dict[str, str]] = {}
    for key, relative in selected.items():
        if not isinstance(relative, str):
            raise DeliveryControlError(f"approved source path is invalid: {key}")
        path = _safe_source(root, work_id, relative)
        snapshots[key] = {"path": relative, "sha256": hashlib.sha256(path.read_bytes()).hexdigest()}
    return snapshots


def _event_exists(events: Path, event: dict[str, Any]) -> bool:
    if not events.exists():
        return False
    for line in events.read_text().splitlines():
        if not line.strip():
            continue
        try:
            existing = json.loads(line)
        except json.JSONDecodeError:
            continue
        if (
            existing.get("event") == event.get("event")
            and existing.get("delivery_charter_digest") == event.get("delivery_charter_digest")
            and existing.get("owner_generation") == event.get("owner_generation")
        ):
            return True
    return False


def _append_event(events: Path, event: dict[str, Any]) -> None:
    # A repeated append is prevented by the authority digest. A crash before
    # this append is recoverable: replay sees run.json and reconciles it.
    if _event_exists(events, event):
        return
    ensure_dir(events.parent)
    with events.open("a") as handle:
        handle.write(canonical(event) + "\n")


def _write_immutable(path: Path, payload: dict[str, Any]) -> None:
    content = json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    if path.exists():
        if path.read_text() != content:
            raise DeliveryControlError(f"immutable artifact conflict: {path.name}")
        return
    write_atomic(path, content)


def start_plan(work_id: str, *, root: Path, expected_updated_at: str | None = None, failure_point: str | None = None) -> tuple[bool, dict[str, Any], list[str]]:
    """Seal delivery authority. ``run.json`` is the only authority commit point."""
    root, run_dir = root.resolve(), (root / ".flow" / "runs" / work_id)
    run_path, events_path = run_dir / "run.json", run_dir / "events.jsonl"
    if not run_path.is_file():
        return False, {}, ["run not found"]
    with run_lock(run_dir):
        try:
            current = json.loads(run_path.read_text())
            if expected_updated_at is not None and current.get("updated_at") != expected_updated_at:
                return False, current, ["stale run revision"]
            state = current.get("state")
            snapshots = _source_snapshot(root, work_id, current.get("artifacts", {}))
            approved_digests = current.get("approved_artifact_digests", {})
            for name, source in snapshots.items():
                if approved_digests.get(name) != source["sha256"]:
                    return False, current, [f"approved {name} changed after approval"]
            if state == "planning" and current.get("delivery"):
                delivery = current["delivery"]
                if delivery.get("source_digests") != snapshots:
                    return False, current, ["approved source bytes changed after delivery authority was sealed"]
                _append_event(events_path, {
                    "at": current.get("updated_at"), "event": "start-plan", "from": state,
                    "to": state, "delivery_charter_digest": delivery["charter_digest"],
                    "owner_generation": delivery["owner_generation"], "reconciled": True,
                })
                return True, current, []
            if state not in {"definition_approved", "solution_approved"}:
                return False, current, [f"invalid transition: start-plan requires definition_approved or solution_approved; current state is {state or '<new>'}"]

            intent_path = _safe_source(root, work_id, snapshots["shaper_intent"]["path"])
            try:
                approved_intent = json.loads(intent_path.read_text())
            except json.JSONDecodeError as exc:
                raise DeliveryControlError("approved Shaper intent is invalid JSON") from exc
            shaper = build_shaper_contract(work_id, snapshots, approved_intent)
            charter = build_delivery_charter(shaper)
            handoff = {
                "schema_version": 1, "kind": "definition_to_delivery_handoff", "run_id": work_id,
                "shaper_contract_id": shaper["shaper_contract_id"], "shaper_contract_digest": shaper["digest"],
                "delivery_charter_id": charter["charter_id"], "delivery_charter_digest": charter["digest"],
                "source_digests": snapshots, "transition": "start-plan",
            }
            handoff["digest"] = digest(handoff)
            attempt_id = f"logical-{charter['digest'][:20]}"
            claim = {
                "schema_version": 1, "kind": "delivery_lead_claim", "logical_delivery_attempt_id": attempt_id,
                "owner": "delivery-lead", "generation": 1, "status": "active", "charter_digest": charter["digest"],
                "supersedes": None,
            }
            claim["digest"] = digest(claim)
            if failure_point == "before-staging":
                raise OSError("injected failure before staging")
            # Staging is keyed by the authority digest. A crashed, unreferenced
            # stage can never conflict with a later source-corrected retry.
            delivery_dir = run_dir / "delivery" / charter["digest"]
            _write_immutable(delivery_dir / "shaper-contract.json", shaper)
            _write_immutable(delivery_dir / "delivery-charter.json", charter)
            _write_immutable(delivery_dir / "handoff.json", handoff)
            _write_immutable(delivery_dir / "lead-claim.json", claim)
            if failure_point == "after-staging":
                raise OSError("injected failure after staging")
            now = _now()
            next_run = dict(current)
            next_run.update({"state": "planning", "lane": "plan", "phase": "planning", "updated_at": now, "last_event": "start-plan"})
            next_run["gates"] = dict(current.get("gates", {}), **{"start-plan": now})
            next_run["delivery"] = {
                "shaper_contract_id": shaper["shaper_contract_id"], "shaper_contract_digest": shaper["digest"],
                "charter_id": charter["charter_id"], "charter_digest": charter["digest"], "handoff_digest": handoff["digest"],
                "logical_delivery_attempt_id": attempt_id, "lead_claim_digest": claim["digest"], "owner_generation": 1,
                "owner_status": "active", "delivery_artifact_dir": f"delivery/{charter['digest']}",
                "lead_claim_path": f"delivery/{charter['digest']}/lead-claim.json", "source_digests": snapshots,
            }
            if failure_point == "before-run-replace":
                raise OSError("injected failure before authority commit")
            write_atomic(run_path, json.dumps(next_run, ensure_ascii=False, indent=2, sort_keys=True) + "\n")
            if failure_point == "after-run-replace":
                return True, next_run, []
            _append_event(events_path, {
                "at": now, "event": "start-plan", "from": state, "to": "planning",
                "delivery_charter_digest": charter["digest"], "handoff_digest": handoff["digest"],
                "logical_delivery_attempt_id": attempt_id, "owner_generation": 1,
            })
            if failure_point == "after-event-append":
                raise OSError("injected failure after event append")
            return True, next_run, []
        except (DeliveryControlError, ValueError, OSError) as exc:
            return False, json.loads(run_path.read_text()), [str(exc)]


def change_lead_claim(
    work_id: str,
    action: str,
    *,
    root: Path,
    owner: str | None = None,
    expected_generation: int | None = None,
) -> tuple[bool, dict[str, Any], list[str]]:
    """Apply an explicit, generation-fenced Delivery Lead recovery action.

    This is intentionally separate from generic lifecycle pause/resume.  A
    lifecycle transition cannot silently change the actor allowed to dispatch.
    """
    if action not in {"attention", "release", "resume", "supersede"}:
        return False, {}, ["unknown lead action"]
    root, run_dir = root.resolve(), (root / ".flow" / "runs" / work_id)
    run_path = run_dir / "run.json"
    if not run_path.is_file():
        return False, {}, ["run not found"]
    with run_lock(run_dir):
        current = json.loads(run_path.read_text())
        delivery = current.get("delivery")
        if not isinstance(delivery, dict):
            return False, current, ["delivery authority is not sealed"]
        generation = delivery.get("owner_generation")
        if not isinstance(generation, int) or generation < 1:
            return False, current, ["delivery owner generation is invalid"]
        if expected_generation is not None and expected_generation != generation:
            return False, current, ["stale delivery owner generation"]
        status = delivery.get("owner_status")
        if action == "attention":
            if status != "active":
                return False, current, ["only an active Delivery Lead can require attention"]
            next_generation, next_status = generation, "attention_required"
        elif action == "release":
            if status not in {"active", "attention_required"}:
                return False, current, ["only an active or attention-required Delivery Lead can release"]
            next_generation, next_status = generation, "released"
        else:
            if status not in {"attention_required", "released", "active"}:
                return False, current, ["Delivery Lead cannot be resumed or superseded from its current status"]
            if not owner or not owner.strip():
                return False, current, ["resume or supersede requires an explicit owner identity"]
            next_generation, next_status = generation + 1, "active"
        previous_relative = delivery.get("lead_claim_path")
        if not isinstance(previous_relative, str) or not previous_relative.startswith("delivery/"):
            return False, current, ["current Delivery Lead claim path is invalid"]
        previous_claim = run_dir / previous_relative
        if not previous_claim.is_file():
            return False, current, ["current Delivery Lead claim is unavailable"]
        with ExitStack() as fences:
            if action in {"resume", "supersede", "release"}:
                refusal = _fence_and_seal_attempts(run_dir, work_id, fences, action=action,
                                                   lead_generation=generation, successor_generation=next_generation)
                if refusal:
                    return False, current, [refusal]
            return _write_lead_claim(run_dir, run_path, current, delivery, action, status, owner,
                                     previous_relative, previous_claim, next_generation, next_status)


def _fence_and_seal_attempts(run_dir: Path, work_id: str, fences: ExitStack, *, action: str,
                             lead_generation: int, successor_generation: int) -> str | None:
    """Refuse a lead change on ledger uncertainty or a live run, else seal superseded attempts.

    The caller holds ``run_lock``. Each attempt's ``recovery_lock`` is only
    probed without waiting, so taking it here, inside ``run_lock``, cannot
    deadlock with a recovery that holds it and waits for ``run_lock``. The
    probes stay held until the claim is written, so no recovery or live run
    can start on a sealed attempt. Returns a stable reason on refusal.
    """
    # Imported lazily: the ledger must not become an import-time dependency
    # of the lifecycle kernel (ADR 0014 keeps it a separate authority).
    from delivery_recovery import LEAD_GUARD_LEDGER_UNREADABLE, RecoveryRefused
    from execution_ledger import ContractError, ExecutionLedger
    import sqlite3
    execution_dir = run_dir / "execution"
    ledger_path = execution_dir / "ledger.sqlite"
    if ledger_path.is_symlink():
        return LEAD_GUARD_LEDGER_UNREADABLE
    if not ledger_path.exists():
        # No ledger yet is not a blocker, but attempt directories without one
        # mean it was lost: never read that as "no uncertain sends".
        attempts_exist = execution_dir.is_dir() and any(execution_dir.glob("*/envelope.json"))
        return LEAD_GUARD_LEDGER_UNREADABLE if attempts_exist else None
    unreadable = (sqlite3.Error, OSError, LookupError, TypeError, ValueError)
    try:
        reader = ExecutionLedger(ledger_path, read_only=True)
        if action == "release":
            # Release stays the way to abandon uncertain work, so it is never
            # blocked by it; it touches only attempts with open expansions.
            attempts = reader.open_expansion_attempts(work_id)
        else:
            if reader.lead_change_blocker():
                return "reconciliation_required: an uncertain send blocks the Delivery Lead successor"
            attempts = reader.started_v8_attempts(work_id, max_lead_generation=lead_generation)
    except unreadable:
        return LEAD_GUARD_LEDGER_UNREADABLE
    try:
        for attempt_id in attempts:
            fences.enter_context(reader.recovery_lock(attempt_id, holder="recovery"))
        if attempts and action == "release":
            # A release keeps the attempts started but ends their pending
            # expansion decisions; the fences make it exclude a decide.
            ExecutionLedger(ledger_path).release_expansions(work_id, expected=attempts)
        elif attempts:
            ExecutionLedger(ledger_path).seal_superseded_attempts(
                work_id, lead_generation=lead_generation, successor_generation=successor_generation,
                action=action, expected=attempts)
    except RecoveryRefused as exc:
        return str(exc)
    except (ContractError, *unreadable):
        # ContractError is a ValueError; listed for the reader.
        return LEAD_GUARD_LEDGER_UNREADABLE
    return None


def _write_lead_claim(run_dir: Path, run_path: Path, current: dict[str, Any], delivery: dict[str, Any],
                      action: str, status: str, owner: str | None, previous_relative: str, previous_claim: Path,
                      next_generation: int, next_status: str) -> tuple[bool, dict[str, Any], list[str]]:
    claim = {
        "schema_version": 1, "kind": "delivery_lead_claim",
        "logical_delivery_attempt_id": delivery["logical_delivery_attempt_id"],
        "owner": owner.strip() if action in {"resume", "supersede"} else json.loads(previous_claim.read_text())["owner"],
        "generation": next_generation, "status": next_status,
        "charter_digest": delivery["charter_digest"],
        "supersedes": delivery["lead_claim_digest"],
    }
    claim["digest"] = digest(claim)
    claim_name = f"lead-claim-g{next_generation}-{next_status}.json"
    claim_relative = f"{previous_relative.rsplit('/', 1)[0]}/{claim_name}"
    _write_immutable(run_dir / claim_relative, claim)
    now = _now()
    next_run = dict(current)
    next_delivery = dict(delivery)
    next_delivery.update({
        "lead_claim_digest": claim["digest"], "owner_generation": next_generation,
        "owner_status": next_status, "lead_claim_path": claim_relative,
    })
    next_run["delivery"] = next_delivery
    next_run["updated_at"] = now
    write_atomic(run_path, json.dumps(next_run, ensure_ascii=False, indent=2, sort_keys=True) + "\n")
    _append_event(run_dir / "events.jsonl", {
        "at": now, "event": f"delivery-lead-{action}", "from": status, "to": next_status,
        "delivery_charter_digest": delivery["charter_digest"], "owner_generation": next_generation,
    })
    return True, next_run, []

"""Structural validation for Flow orchestration contracts.

The validator deliberately proves declarations, not hidden runtime state or
semantic truth.  It never reads referenced artifact contents; existence and
declared relationships are the enforceable boundary.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, NamedTuple

from fsutil import repo_root


SCHEMA_VERSION = 1
MANIFEST_FILE = "orchestration.json"
STAGES = ("dispatch", "handback", "acceptance")
MODES = {"single", "delegated", "shared-mutation"}
CAPABILITY_STATES = {"confirmed", "missing", "unknown"}
CLAIM_STATUSES = {"observed", "inferred", "recommended", "unverified"}
CLAIM_DISPOSITIONS = {"accepted", "rejected", "deferred"}
IDENTITY_KINDS = {"human", "agent", "external_provider"}
MUTATION_TYPES = {"additive", "structural", "destructive", "read-only"}
RECOVERY_STATES = {
    "exercised",
    "available_unexercised",
    "irreversible_acknowledged",
}
UNEXPECTED_DELTA_STATES = {"none", "resolved", "accepted", "unresolved"}
HARD_TRIGGERS = {
    "destructive_or_irreversible",
    "production_or_shared_external_mutation",
    "security_or_privacy_boundary",
    "loss_bearing_data_migration",
    "regulated_personnel_safety_or_customer_access",
}
AGGRAVATING_FACTORS = {
    "large_blast_radius",
    "weak_rollback",
    "weak_or_delayed_observability",
    "concurrency_or_cross_system_coordination",
    "material_unresolved_ambiguity",
    "author_only_validation",
    "unverified_claim_for_durable_truth",
}


def valid_work_id(value: Any) -> bool:
    return (
        isinstance(value, str)
        and bool(value)
        and value not in {".", ".."}
        and "/" not in value
        and "\\" not in value
        and "\x00" not in value
    )


def _enum(value: Any, allowed: set[str]) -> bool:
    return isinstance(value, str) and value in allowed


class Finding(NamedTuple):
    field: str
    subject: str
    rule: str
    message: str
    action: str


def manifest_path(work_id: str, root: Path | None = None) -> Path:
    if not valid_work_id(work_id):
        raise ValueError("work id must be a non-empty run-directory name and may not contain path separators")
    return (root or repo_root()) / ".flow" / "runs" / work_id / MANIFEST_FILE


def calculated_risk(hard_triggers: list[str], aggravating_factors: list[str]) -> str:
    return "high" if hard_triggers or len(aggravating_factors) >= 2 else "standard"


def _finding(
    findings: list[Finding],
    field: str,
    subject: str,
    rule: str,
    message: str,
    action: str,
) -> None:
    findings.append(Finding(field, subject, rule, message, action))


def _list(value: Any) -> list[Any]:
    return value if isinstance(value, list) else []


def _dict(value: Any) -> dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _nonempty(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _safe_repo_path(raw: Any, root: Path) -> Path | None:
    if not _nonempty(raw):
        return None
    candidate = Path(raw)
    if candidate.is_absolute() or ".." in candidate.parts:
        return None
    resolved = (root / candidate).resolve()
    try:
        resolved.relative_to(root.resolve())
    except ValueError:
        return None
    return resolved


def _path_exists(
    findings: list[Finding], root: Path, raw: Any, field: str, subject: str
) -> Path | None:
    path = _safe_repo_path(raw, root)
    if path is None:
        _finding(
            findings,
            field,
            subject,
            "safe-repository-path",
            "the declared path is empty, absolute, or escapes the repository",
            "use a repository-relative path without parent traversal",
        )
    elif not path.is_file():
        _finding(
            findings,
            field,
            subject,
            "referenced-artifact-exists",
            "the referenced artifact is missing or is not a regular file",
            "create the file at the declared path before this stage",
        )
    return path


def _path_within(path: Path, scope: Path) -> bool:
    return path == scope or scope in path.parents


def _paths_overlap(left: Path, right: Path) -> bool:
    return _path_within(left, right) or _path_within(right, left)


def _identity_key(value: Any) -> tuple[str, str] | None:
    identity = _dict(value)
    kind = identity.get("kind")
    identifier = identity.get("id")
    if not _enum(kind, IDENTITY_KINDS) or not _nonempty(identifier):
        return None
    return kind, identifier.strip()


def _validate_identity(
    findings: list[Finding], value: Any, field: str, subject: str
) -> tuple[str, str] | None:
    key = _identity_key(value)
    if key is None:
        _finding(
            findings,
            field,
            subject,
            "identity-provenance",
            "identity must declare a supported kind and a non-empty id",
            "set kind to human, agent, or external_provider and record the stable id",
        )
    return key


def _validate_common(
    data: Any, work_id: str, root: Path, findings: list[Finding]
) -> tuple[dict[str, Any], str]:
    if not isinstance(data, dict):
        _finding(
            findings,
            "$",
            work_id,
            "manifest-object",
            "the orchestration manifest must be a JSON object",
            "replace it with an object using the orchestration template",
        )
        return {}, "standard"
    if data.get("schema_version") != SCHEMA_VERSION:
        _finding(
            findings,
            "schema_version",
            work_id,
            "supported-schema",
            f"schema_version must be {SCHEMA_VERSION}",
            f"set schema_version to {SCHEMA_VERSION}",
        )
    if data.get("work_id") != work_id:
        _finding(
            findings,
            "work_id",
            work_id,
            "containing-run-identity",
            "work_id does not match the containing run",
            f"set work_id to {work_id}",
        )
    if not _enum(data.get("mode"), MODES):
        _finding(
            findings,
            "mode",
            work_id,
            "controlled-mode",
            "mode is not a supported value",
            "use single, delegated, or shared-mutation",
        )

    if not isinstance(data.get("risk"), dict):
        _finding(findings, "risk", work_id, "risk-object", "risk must be an object", "declare controlled triggers, calculated classification, and rationale")
    risk = _dict(data.get("risk"))
    if not isinstance(risk.get("hard_triggers"), list):
        _finding(findings, "risk.hard_triggers", work_id, "risk-trigger-list", "hard_triggers must be a list", "declare zero or more controlled hard triggers")
    if not isinstance(risk.get("aggravating_factors"), list):
        _finding(findings, "risk.aggravating_factors", work_id, "risk-factor-list", "aggravating_factors must be a list", "declare zero or more controlled aggravating factors")
    hard = _list(risk.get("hard_triggers"))
    factors = _list(risk.get("aggravating_factors"))
    for index, value in enumerate(hard):
        if not _enum(value, HARD_TRIGGERS):
            _finding(
                findings,
                f"risk.hard_triggers[{index}]",
                work_id,
                "controlled-risk-trigger",
                "hard trigger is not recognized",
                "use a hard trigger defined by the orchestration standard",
            )
    for index, value in enumerate(factors):
        if not _enum(value, AGGRAVATING_FACTORS):
            _finding(
                findings,
                f"risk.aggravating_factors[{index}]",
                work_id,
                "controlled-risk-factor",
                "aggravating factor is not recognized",
                "use an aggravating factor defined by the orchestration standard",
            )
    expected = calculated_risk(hard, factors)
    if risk.get("classification") != expected:
        _finding(
            findings,
            "risk.classification",
            work_id,
            "calculated-risk",
            f"stored classification conflicts with calculated classification {expected}",
            f"set classification to {expected} or correct the controlled triggers",
        )
    if not _nonempty(risk.get("rationale")):
        _finding(
            findings,
            "risk.rationale",
            work_id,
            "risk-rationale",
            "risk rationale is missing",
            "record why the selected triggers apply",
        )
    return data, expected


def _validate_dispatch(
    data: dict[str, Any], root: Path, findings: list[Finding]
) -> None:
    assignments = data.get("assignments")
    if not isinstance(assignments, list) or not assignments:
        _finding(
            findings,
            "assignments",
            "manifest",
            "assignment-required",
            "at least one assignment is required",
            "add a complete provider assignment",
        )
        return
    if data.get("mode") == "delegated" and len(assignments) < 2:
        _finding(findings, "assignments", "manifest", "delegated-provider-count", "delegated mode has fewer than two assignments", "declare the delegated provider assignment or use single mode")

    seen: set[str] = set()
    writable: list[tuple[str, Path, str, bool]] = []
    assignment_ids: set[str] = set()
    for index, raw in enumerate(assignments):
        field = f"assignments[{index}]"
        item = _dict(raw)
        assignment_id = item.get("id")
        subject = assignment_id if _nonempty(assignment_id) else field
        if not _nonempty(assignment_id) or assignment_id in seen:
            _finding(
                findings,
                f"{field}.id",
                subject,
                "unique-assignment-id",
                "assignment id is missing or duplicated",
                "provide a stable id unique within the manifest",
            )
        else:
            seen.add(assignment_id)
            assignment_ids.add(assignment_id)
        if not _nonempty(item.get("lane")) or not _nonempty(item.get("role")):
            _finding(
                findings,
                field,
                subject,
                "provider-role",
                "lane and role are required",
                "declare the Flow lane and provider role",
            )
        _validate_identity(findings, item.get("provider"), f"{field}.provider", subject)
        _path_exists(findings, root, item.get("brief_path"), f"{field}.brief_path", subject)
        if not isinstance(item.get("input_evidence"), list):
            _finding(findings, f"{field}.input_evidence", subject, "input-evidence-list", "input evidence must be a list", "declare the evidence inventory paths")
        for evidence_index, evidence in enumerate(_list(item.get("input_evidence"))):
            _path_exists(
                findings,
                root,
                evidence,
                f"{field}.input_evidence[{evidence_index}]",
                subject,
            )
        read_scopes = item.get("read_scopes")
        if not isinstance(read_scopes, list) or not read_scopes:
            _finding(findings, f"{field}.read_scopes", subject, "read-scope-inventory", "read scopes are missing", "declare the repository areas the provider may inspect")
        for scope_index, scope in enumerate(_list(read_scopes)):
            if _safe_repo_path(scope, root) is None:
                _finding(findings, f"{field}.read_scopes[{scope_index}]", subject, "safe-read-scope", "read scope is empty, absolute, or escapes the repository", "use a repository-relative read scope")
        read_only = item.get("read_only") is True
        write_scopes = _list(item.get("write_scopes"))
        if read_only and write_scopes:
            _finding(
                findings,
                f"{field}.write_scopes",
                subject,
                "read-only-write-scope",
                "a read-only assignment declares write scopes",
                "remove product write scopes or set read_only to false",
            )
        if not read_only and not write_scopes:
            _finding(
                findings,
                f"{field}.write_scopes",
                subject,
                "writable-scope-required",
                "a writable assignment has no write scope",
                "declare the exact repository write scope",
            )
        scope_paths: list[Path] = []
        for scope_index, scope in enumerate(write_scopes):
            path = _safe_repo_path(scope, root)
            if path is None:
                _finding(
                    findings,
                    f"{field}.write_scopes[{scope_index}]",
                    subject,
                    "safe-write-scope",
                    "write scope is empty, absolute, or escapes the repository",
                    "use a repository-relative scope without parent traversal",
                )
            else:
                scope_paths.append(path)
        coordination = _dict(item.get("coordination"))
        group = coordination.get("group")
        serialized = coordination.get("mode") == "serialized"
        if not _enum(coordination.get("mode"), {"concurrent", "serialized"}) or not _nonempty(group):
            _finding(
                findings,
                f"{field}.coordination",
                subject,
                "coordination-contract",
                "coordination must declare concurrent or serialized mode and a group",
                "declare the execution mode and stable coordination group",
            )
        for scope_path in scope_paths:
            writable.append((subject, scope_path, str(group), serialized))

        capabilities = item.get("required_capabilities")
        if not isinstance(capabilities, list):
            _finding(
                findings,
                f"{field}.required_capabilities",
                subject,
                "capability-inventory",
                "required capabilities must be a list",
                "declare each required capability and its observed status",
            )
        for capability_index, capability_raw in enumerate(_list(capabilities)):
            capability = _dict(capability_raw)
            cap_field = f"{field}.required_capabilities[{capability_index}]"
            if not _nonempty(capability.get("name")):
                _finding(findings, f"{cap_field}.name", subject, "capability-name", "capability name is missing", "name the required capability")
            status = capability.get("status")
            if not _enum(status, CAPABILITY_STATES):
                _finding(findings, f"{cap_field}.status", subject, "capability-status", "capability status is not recognized", "use confirmed, missing, or unknown")
            elif status != "confirmed":
                _finding(findings, f"{cap_field}.status", subject, "required-capability-confirmed", f"required capability is {status}", "confirm the capability before dispatch or change the assignment")

        output = _dict(item.get("output"))
        output_path = _safe_repo_path(output.get("path"), root)
        if output_path is None or not _nonempty(output.get("format")):
            _finding(findings, f"{field}.output", subject, "declared-output", "output requires a safe path and format", "declare the output path and format")
        elif read_only:
            run_output_root = root / ".flow" / "runs" / str(data.get("work_id"))
            if not _path_within(output_path, run_output_root):
                _finding(findings, f"{field}.output.path", subject, "read-only-run-output", "read-only assignment output is outside its run artifact directory", "write the report under the containing run")
        elif not any(_path_within(output_path, scope) for scope in scope_paths):
            _finding(findings, f"{field}.output.path", subject, "output-within-write-scope", "output is not inside a declared write scope", "expand the write scope explicitly or move the output")
        if not _list(item.get("success_criteria")):
            _finding(findings, f"{field}.success_criteria", subject, "success-criteria", "success criteria are missing", "add one or more observable success criteria")
        statuses = _list(item.get("claim_statuses"))
        if not statuses or any(not _enum(value, CLAIM_STATUSES) for value in statuses):
            _finding(findings, f"{field}.claim_statuses", subject, "claim-status-expectation", "claim status expectations are missing or invalid", "declare one or more supported claim statuses")

    for left_index, left in enumerate(writable):
        for right in writable[left_index + 1 :]:
            if left[0] == right[0] or not _paths_overlap(left[1], right[1]):
                continue
            if left[2] == right[2] and left[3] and right[3]:
                continue
            _finding(
                findings,
                "assignments.write_scopes",
                f"{left[0]} / {right[0]}",
                "concurrent-write-overlap",
                "assignment write scopes overlap without shared serialization",
                "make the scopes disjoint or serialize both assignments in one group",
            )

    _validate_shared_dispatch(data, assignment_ids, findings)
    if any(
        _dict(target).get("mutation_type") != "read-only"
        for target in _list(data.get("shared_state"))
    ) and "production_or_shared_external_mutation" not in _list(
        _dict(data.get("risk")).get("hard_triggers")
    ):
        _finding(
            findings,
            "risk.hard_triggers",
            "manifest",
            "shared-mutation-risk-trigger",
            "a shared mutation is declared without its required hard trigger",
            "add production_or_shared_external_mutation and store the calculated high classification",
        )


def _validate_shared_dispatch(
    data: dict[str, Any], assignment_ids: set[str], findings: list[Finding]
) -> None:
    targets = data.get("shared_state", [])
    if not isinstance(targets, list):
        _finding(findings, "shared_state", "manifest", "shared-state-list", "shared_state must be a list", "declare zero or more shared targets")
        return
    if data.get("mode") == "shared-mutation" and not targets:
        _finding(findings, "shared_state", "manifest", "shared-target-required", "shared-mutation mode has no shared target", "declare each shared target or use another mode")
    seen: set[str] = set()
    parsed: list[tuple[str, str, str, str, bool, str]] = []
    for index, raw in enumerate(targets):
        field = f"shared_state[{index}]"
        item = _dict(raw)
        target_id = item.get("id")
        subject = target_id if _nonempty(target_id) else field
        if not _nonempty(target_id) or target_id in seen:
            _finding(findings, f"{field}.id", subject, "unique-target-id", "shared target id is missing or duplicated", "provide a stable unique target id")
        else:
            seen.add(target_id)
        if not _nonempty(item.get("kind")) or not _nonempty(item.get("identity")):
            _finding(findings, field, subject, "exact-target-identity", "target kind and exact identity are required", "record the target kind and stable exact identity")
        mutation = item.get("mutation_type")
        if not _enum(mutation, MUTATION_TYPES):
            _finding(findings, f"{field}.mutation_type", subject, "controlled-mutation-type", "mutation type is not recognized", "use additive, structural, destructive, or read-only")
        if not _nonempty(item.get("owner_assignment")) or item.get("owner_assignment") not in assignment_ids:
            _finding(findings, f"{field}.owner_assignment", subject, "known-assignment-owner", "target owner does not name a declared assignment", "set the owner to a declared assignment id")
        if not _nonempty(item.get("write_region")):
            _finding(findings, f"{field}.write_region", subject, "declared-write-region", "write region is missing", "declare the exact external region or read-only extent")
        coordination = _dict(item.get("coordination"))
        if not _enum(coordination.get("mode"), {"concurrent", "serialized"}) or not _nonempty(coordination.get("group")):
            _finding(findings, f"{field}.coordination", subject, "shared-coordination", "coordination must declare mode and group", "declare concurrent or serialized coordination")
        parsed.append((subject, str(item.get("identity")), str(item.get("write_region")), str(coordination.get("group")), coordination.get("mode") == "serialized", str(mutation)))
    for left_index, left in enumerate(parsed):
        for right in parsed[left_index + 1 :]:
            if left[1] != right[1]:
                continue
            if left[3] == right[3] and left[4] and right[4]:
                continue
            both_additive = left[5] == right[5] == "additive"
            if both_additive and left[2] != right[2]:
                continue
            if "read-only" in {left[5], right[5]}:
                continue
            _finding(findings, "shared_state", f"{left[0]} / {right[0]}", "shared-region-conflict", "shared-target mutations conflict without serialization", "serialize structural or destructive operations; additive operations may instead declare non-overlapping regions")


def _validate_handback(
    data: dict[str, Any], root: Path, findings: list[Finding]
) -> None:
    for index, raw in enumerate(_list(data.get("assignments"))):
        item = _dict(raw)
        subject = item.get("id", f"assignments[{index}]")
        output = _dict(item.get("output"))
        _path_exists(findings, root, output.get("path"), f"assignments[{index}].output.path", subject)

    reconciliation = _dict(data.get("reconciliation"))
    _path_exists(findings, root, reconciliation.get("artifact_path"), "reconciliation.artifact_path", "reconciliation")
    if reconciliation.get("status") != "resolved":
        _finding(findings, "reconciliation.status", "reconciliation", "resolved-reconciliation", "reconciliation is not resolved", "resolve or explicitly disposition every material conflict")
    claims = _list(reconciliation.get("claims"))
    claim_by_id = {
        claim.get("id"): claim
        for claim in (_dict(raw) for raw in claims)
        if _nonempty(claim.get("id"))
    }
    if len(claim_by_id) != len([claim for claim in claims if _nonempty(_dict(claim).get("id"))]):
        _finding(findings, "reconciliation.claims", "reconciliation", "unique-claim-id", "material claim ids are duplicated", "give every material claim a stable unique id")
    for index, raw in enumerate(claims):
        claim = _dict(raw)
        subject = claim.get("id", f"claim[{index}]")
        status = claim.get("status")
        if not _enum(status, CLAIM_STATUSES):
            _finding(findings, f"reconciliation.claims[{index}].status", subject, "claim-status", "claim status is not recognized", "use observed, inferred, recommended, or unverified")
        if status == "observed":
            evidence = _list(claim.get("evidence"))
            if not evidence:
                _finding(findings, f"reconciliation.claims[{index}].evidence", subject, "observed-evidence", "observed claim has no evidence reference", "cite the observation evidence")
            for evidence_index, evidence_path in enumerate(evidence):
                _path_exists(findings, root, evidence_path, f"reconciliation.claims[{index}].evidence[{evidence_index}]", subject)
        if status == "inferred":
            supports = _list(claim.get("supports"))
            if not supports or any(not _nonempty(support) or _dict(claim_by_id.get(support)).get("status") != "observed" for support in supports):
                _finding(findings, f"reconciliation.claims[{index}].supports", subject, "inference-support", "inferred claim does not link declared observed claims", "link one or more observed claim ids")
        if status == "recommended" and _identity_key(claim.get("decision_owner")) is None:
            _finding(findings, f"reconciliation.claims[{index}].decision_owner", subject, "recommendation-owner", "recommended claim lacks decision ownership", "record the accountable identity")
        disposition = claim.get("disposition")
        if not _enum(disposition, CLAIM_DISPOSITIONS):
            _finding(findings, f"reconciliation.claims[{index}].disposition", subject, "claim-disposition", "material claim has no supported disposition", "set accepted, rejected, or deferred")
        if status == "unverified" and disposition == "accepted":
            _finding(findings, f"reconciliation.claims[{index}].disposition", subject, "unverified-not-fact", "an unverified claim cannot be accepted as durable fact", "verify it, reject it, or defer it")

    for index, raw in enumerate(_list(data.get("shared_state"))):
        item = _dict(raw)
        if item.get("mutation_type") == "read-only":
            continue
        subject = item.get("id", f"shared_state[{index}]")
        for key in ("baseline_artifact", "execution_result_artifact", "readback_artifact", "comparison_artifact"):
            _path_exists(findings, root, item.get(key), f"shared_state[{index}].{key}", subject)
        if not _nonempty(item.get("baseline_captured_at")) or not _nonempty(item.get("baseline_source_identity")):
            _finding(findings, f"shared_state[{index}].baseline", subject, "fresh-baseline-provenance", "baseline capture time or source identity is missing", "record the immediately pre-write capture time and source identity")
        if not _nonempty(item.get("expected_delta")):
            _finding(findings, f"shared_state[{index}].expected_delta", subject, "expected-delta", "expected delta is missing", "state the exact intended change")
        recovery = item.get("recovery_state")
        if not _enum(recovery, RECOVERY_STATES):
            _finding(findings, f"shared_state[{index}].recovery_state", subject, "recovery-posture", "recovery state is not recognized", "record exercised, available_unexercised, or irreversible_acknowledged")
        if item.get("mutation_type") == "destructive" and not _enum(recovery, {"exercised", "irreversible_acknowledged"}):
            _finding(findings, f"shared_state[{index}].recovery_state", subject, "destructive-recovery", "destructive mutation lacks exercised recovery or irreversible acknowledgment", "exercise recovery or record the acknowledgment and safeguards")
        if recovery == "irreversible_acknowledged" and not _nonempty(item.get("recovery_safeguards")):
            _finding(findings, f"shared_state[{index}].recovery_safeguards", subject, "irreversible-safeguards", "irreversible acknowledgment has no recorded safeguards", "record the safeguards and accountable acknowledgment")
        delta = item.get("unexpected_delta_status")
        if not _enum(delta, UNEXPECTED_DELTA_STATES):
            _finding(findings, f"shared_state[{index}].unexpected_delta_status", subject, "unexpected-delta-status", "unexpected delta status is not recognized", "use none, resolved, accepted, or unresolved")
        elif delta == "unresolved" or (_enum(delta, {"resolved", "accepted"}) and not _nonempty(item.get("unexpected_delta_disposition"))):
            _finding(findings, f"shared_state[{index}].unexpected_delta_disposition", subject, "unexpected-delta-disposition", "unexpected delta is unresolved or lacks a disposition", "resolve and record the disposition before handback")


def _validate_acceptance(
    data: dict[str, Any], root: Path, risk: str, findings: list[Finding]
) -> None:
    verification = _dict(data.get("verification"))
    assignments_by_id = {
        assignment.get("id"): assignment
        for assignment in (_dict(raw) for raw in _list(data.get("assignments")))
        if _nonempty(assignment.get("id"))
    }
    assignment_providers = {
        assignment_id: _identity_key(assignment.get("provider"))
        for assignment_id, assignment in assignments_by_id.items()
    }
    producers = verification.get("producer_assignments")
    if not isinstance(producers, list) or not producers:
        _finding(findings, "verification.producer_assignments", "verification", "producer-assignment-inventory", "producer assignments are missing", "list every assignment that produced the accepted work")
        producer_ids: list[str] = []
    else:
        producer_ids = [value for value in producers if _nonempty(value)]
        if len(producer_ids) != len(producers) or len(set(producer_ids)) != len(producer_ids):
            _finding(findings, "verification.producer_assignments", "verification", "producer-assignment-inventory", "producer assignments contain invalid or duplicate ids", "list each producer assignment id exactly once")
    collector_id = verification.get("evidence_collector_assignment")
    verifier_id = verification.get("verifier_assignment")
    collector_key = collector_id if _nonempty(collector_id) else None
    verifier_key = verifier_id if _nonempty(verifier_id) else None
    for field, assignment_ids in (
        ("verification.producer_assignments", producer_ids),
        ("verification.evidence_collector_assignment", [collector_key]),
        ("verification.verifier_assignment", [verifier_key]),
    ):
        for assignment_id in assignment_ids:
            if not _nonempty(assignment_id) or assignment_id not in assignment_providers:
                _finding(findings, field, "verification", "declared-verification-assignment", "verification role does not reference a declared assignment", "reference the stable id of the assignment that performed this role")
    producer_identities = {assignment_providers.get(value) for value in producer_ids} - {None}
    collector = assignment_providers.get(collector_key)
    verifier = assignment_providers.get(verifier_key)
    mutable_owners = {
        target.get("owner_assignment")
        for target in (_dict(raw) for raw in _list(data.get("shared_state")))
        if target.get("mutation_type") != "read-only" and _nonempty(target.get("owner_assignment"))
    }
    if not mutable_owners.issubset(set(producer_ids)):
        _finding(findings, "verification.producer_assignments", "verification", "shared-mutation-producer-binding", "a shared-mutation owner is not recorded as a producer", "include every mutable target owner assignment in producer_assignments")
    writable_assignments = {
        assignment_id
        for assignment_id, assignment in assignments_by_id.items()
        if assignment.get("read_only") is not True
    }
    if not writable_assignments.issubset(set(producer_ids)):
        _finding(findings, "verification.producer_assignments", "verification", "writable-producer-binding", "a writable assignment is not recorded as a producer", "include every writable assignment that produced run output")
    artifact = verification.get("artifact_path")
    if risk == "high":
        _path_exists(findings, root, artifact, "verification.artifact_path", "verification")
        if verifier_key in producer_ids or (verifier is not None and verifier in producer_identities):
            _finding(findings, "verification.verifier_assignment", "verification", "independent-high-risk-verifier", "high-risk verifier assignment or provider also produced the work", "assign a verifier with a distinct assignment and stable provider identity")
        if verifier_key == collector_key or (collector is not None and verifier == collector):
            _finding(findings, "verification.verifier_assignment", "verification", "independent-high-risk-verifier", "high-risk verifier assignment or provider also collected the certified evidence", "assign a verifier who did not collect the certified evidence")
        if _dict(assignments_by_id.get(verifier_key)).get("read_only") is not True:
            _finding(findings, "verification.verifier_assignment", "verification", "read-only-high-risk-verifier", "high-risk verifier assignment is writable", "use a read-only review assignment for independent verification")
        if verification.get("independent") is not True:
            _finding(findings, "verification.independent", "verification", "recorded-verifier-independence", "high-risk verification is not marked independent", "record true after checking identity separation")
    elif artifact:
        _path_exists(findings, root, artifact, "verification.artifact_path", "verification")


def validate_manifest(
    data: Any, work_id: str, stage: str, *, root: Path | None = None
) -> list[Finding]:
    if stage not in STAGES:
        raise ValueError(f"unsupported orchestration stage: {stage}")
    project_root = (root or repo_root()).resolve()
    findings: list[Finding] = []
    manifest, risk = _validate_common(data, work_id, project_root, findings)
    _validate_dispatch(manifest, project_root, findings)
    if stage in {"handback", "acceptance"}:
        _validate_handback(manifest, project_root, findings)
    if stage == "acceptance":
        _validate_acceptance(manifest, project_root, risk, findings)
    return findings


def validate_orchestration(
    work_id: str, stage: str, *, root: Path | None = None
) -> tuple[bool, Path, list[Finding]]:
    if not valid_work_id(work_id):
        project_root = (root or repo_root()).resolve()
        path = project_root / ".flow" / "runs" / "__invalid_work_id__" / MANIFEST_FILE
        finding = Finding(
            "work_id",
            "invalid",
            "safe-work-id",
            "the work id is not a safe run-directory name",
            "use a non-empty single directory name without path separators",
        )
        return False, path, [finding]
    path = manifest_path(work_id, root)
    run_dir = path.parent
    if not run_dir.exists():
        finding = Finding(
            "run",
            work_id,
            "orchestration-run-exists",
            "the workflow run does not exist",
            f"create or transition run {work_id} before validating its contract",
        )
        return False, path, [finding]
    if not path.exists():
        finding = Finding(
            "manifest",
            work_id,
            "orchestration-manifest-exists",
            "the run has no orchestration manifest",
            f"create {path.relative_to((root or repo_root()).resolve())} from the template",
        )
        return False, path, [finding]
    try:
        data = json.loads(path.read_text())
    except json.JSONDecodeError as exc:
        finding = Finding(
            "manifest",
            work_id,
            "valid-json",
            f"the orchestration manifest is invalid JSON at line {exc.lineno}, column {exc.colno}",
            "repair the JSON syntax without adding comments",
        )
        return False, path, [finding]
    findings = validate_manifest(data, work_id, stage, root=root)
    return not findings, path, findings


def result_payload(ok: bool, stage: str, path: Path, findings: list[Finding]) -> dict[str, Any]:
    return {
        "ok": ok,
        "stage": stage,
        "manifest": str(path),
        "findings": [finding._asdict() for finding in findings],
        "limitations": [
            "external region overlap is declaration-level only",
            "runtime capability grants and semantic truth are not inspected",
        ],
    }


def cmd_validate(args) -> int:
    try:
        ok, path, findings = validate_orchestration(args.work_id, args.stage)
    except ValueError as exc:
        print(str(exc))
        return 1
    payload = result_payload(ok, args.stage, path, findings)
    if args.json:
        print(json.dumps(payload, indent=2, sort_keys=True))
    elif ok:
        print(f"orchestration valid: {args.work_id} ({args.stage})")
        print(f"manifest: {path}")
    else:
        print(f"orchestration invalid: {args.work_id} ({args.stage})")
        print(f"manifest: {path}")
        for finding in findings:
            print(f"- {finding.field} [{finding.rule}]: {finding.message}; {finding.action}")
    if not args.json:
        print("limit: external region overlap is declaration-level only; runtime grants and semantic truth are not inspected")
    return 0 if ok else 1

